WITH target AS (
 SELECT t.* FROM tickets t WHERE
 (NULLIF($1::jsonb->>'ticketId','') IS NOT NULL AND t.id=(NULLIF($1::jsonb->>'ticketId',''))::int)
 OR (NULLIF($1::jsonb->>'ticketId','') IS NULL AND EXISTS (
